const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: 'new' });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('PAGE ERROR:', e.message));
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE ERR:', m.text()); });
  const url = 'http://localhost:3107/index.html';
  const res = await page.goto(url, { waitUntil: 'load', timeout: 45000 });
  console.log('load status:', res.status());
  await page.waitForTimeout(1500);
  await page.click('#startBtn');
  await page.waitForTimeout(1200);
  // walk forward to verify movement + collision
  await page.keyboard.down('KeyW');
  await page.waitForTimeout(1500);
  await page.keyboard.up('KeyW');
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/opencode/check-1.jpg', type: 'jpeg', quality: 78 });
  console.log('screenshot saved');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

