const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => { errors.push('PAGE: '+e.message); if(errors.length<=5) console.log('PAGE ERROR:', e.message); });
  page.on('console', m => { if(m.type()==='error' && errors.length<8) console.log('CONSOLE:', m.text()); });
  await page.goto('http://localhost:3107/index.html', { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(2000);
  // sample center pixel of canvas before any interaction
  const c1 = await page.evaluate(() => {
    const c = document.querySelector('canvas');
    const x = c.getContext('2d');
    const d = x.getImageData(c.width/2, c.height/2, 1, 1).data;
    return { w: c.width, h: c.height, rgb: [d[0],d[1],d[2]] };
  });
  console.log('canvas center before start:', JSON.stringify(c1));
  await page.screenshot({ path: '/tmp/opencode/diag-before.jpg', type: 'jpeg', quality: 70 });
  await page.click('#startBtn');
  await page.waitForTimeout(1500);
  const c2 = await page.evaluate(() => {
    const c = document.querySelector('canvas');
    const x = c.getContext('2d');
    const d = x.getImageData(c.width/2, c.height/2, 1, 1).data;
    return { rgb: [d[0],d[1],d[2]] };
  });
  console.log('canvas center after start:', JSON.stringify(c2));
  await page.screenshot({ path: '/tmp/opencode/diag-after.jpg', type: 'jpeg', quality: 70 });
  await browser.close();
  console.log('total errors:', errors.length);
})().catch(e => { console.error('FATAL', e); process.exit(1); });

