  await page.waitForTimeout(700);
  await page.evaluate(() => { document.getElementById('start').style.display = 'none'; });
  await page.waitForTimeout(800);

  const state = await page.evaluate(() => {
    const dbs = window.__dbg.doors();
    const cam = window.__dbg.cam();
    return { nDoors: dbs.length, cam, firstDoor: dbs[0] };
  });
  console.log('INIT:', JSON.stringify(state));

  // drive camera toward first door
  const door = state.firstDoor;
  // estimate door world pos from rotation not enough; instead move near origin area & face forward
  await page.evaluate(() => { window.__dbg.moveCam(0, 1.7, 2); window.__dbg.lookAt(0, 1.7, -10); });
  await page.waitForTimeout(600);
  await page.evaluate(() => window.__dbg.interact());
  await page.waitForTimeout(300);

  const after = await page.evaluate(() => {
    const dbs = window.__dbg.doors();
    return { nDoors: dbs.length, anyOpen: dbs.some(d=>d.open), cam: window.__dbg.cam(), label: window.__dbg.label() };
  });
  console.log('AFTER INTERACT:', JSON.stringify(after));
  await page.screenshot({ path: '/tmp/opencode/pt-door.jpg', type: 'jpeg', quality: 78, timeout: 15000 });
  console.log('screenshot ok');
  await browser.close();
  console.log('done. errors:', errors.length);
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => { errors.push(e.message); if(errors.length<=5) console.log('PAGE:', e.message); });
  await page.goto('http://localhost:3107/index.html', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.waitForTimeout(700);
  await page.evaluate(() => { document.getElementById('start').style.display = 'none'; });
  await page.waitForTimeout(800);

  const res = await page.evaluate(() => {
    const dbs = window.__dbg.doors();
    // pick door nearest to camera start (0,1.7,6)
    const cam = {x:0,y:1.7,z:6};
    let best=null,bd=1e9;
    for (const d of dbs) {
      const dx=d.pos.x-cam.x, dy=d.pos.y-cam.y, dz=d.pos.z-cam.z;
      const dist=Math.sqrt(dx*dx+dy*dy+dz*dz);
      if (dist<bd){bd=dist;best={...d,dist};}
    }
    return { nDoors:dbs.length, best };
  });
  console.log('DOORS:', JSON.stringify(res));

  const { best } = res;
  if (best) {
    // stand 1.5 units in front of door (opposite its normal) looking at door
    // door rot closedRot ~ drot; normal points along rotation. Stand behind door looking at it.
