const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => { errors.push(e.message); if(errors.length<=5) console.log('PAGE:', e.message); });
  await page.goto('http://localhost:3107/index.html', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.waitForTimeout(700);
  await page.evaluate(() => { document.getElementById('start').style.display = 'none'; });
  await page.waitForTimeout(800);

  const info = await page.evaluate(() => {
    const dbs = window.__dbg.doors();
    // find a door and compute a camera position 3 units in front looking at door center
    // Use door pos + its forward direction. For a door with closedRot drot, front is along the door normal.
    // We'll just place camera at door pos offset by -normal*3 where normal = dir door faces.
    // Door facing direction: drot=0 -> faces -z (front -z); drot=PI -> faces +z; drot=PI/2 -> faces +x? 
    // Simplest: put camera at doorPos, then offset by (0,0,-3) and lookAt doorPos.
    let best = null;
    for (const d of dbs) {
      if (!d.open) { best = d; break; }
    }
    if (!best) return { nDoors: dbs.length, err: 'no closed door' };
    const ax=best.pos.x, ay=best.pos.y, az=best.pos.z;
    window.__dbg.moveCam(ax, ay+0.5, az-3);   // 3 units in -z from door
    window.__dbg.lookAt(ax, ay, az);
    return { nDoors: dbs.length, door: {ax,ay,az,rot:best.rot}, cam: window.__dbg.cam() };
  });
  console.log('SETUP:', JSON.stringify(info));

  await page.waitForTimeout(400);
  await page.evaluate(() => window.__dbg.interact());
  await page.waitForTimeout(300);

  const after = await page.evaluate(() => {
    const dbs = window.__dbg.doors();
    return { nDoors: dbs.length, openCount: dbs.filter(d=>d.open).length, label: window.__dbg.label() };
  });
  console.log('AFTER:', JSON.stringify(after));
  await page.screenshot({ path: '/tmp/opencode/pt2.jpg', type: 'jpeg', quality: 78, timeout: 15000 });
  console.log('screenshot ok');
  await browser.close();
  console.log('done. errors:', errors.length);
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

