function beginLoading() {
  startScreen.style.display = 'none';
  loader.style.display = 'flex';
  const steps = ['Generating blocks…', 'Paving streets…', 'Placing buildings…', 'Lighting interiors…', 'Ready.'];
  let i = 0;
