    mx = stick.x * right.x + stick.y * dir.x;
    mz = stick.x * right.z + stick.y * dir.z;
  }
  let len = Math.sqrt(mx * mx + mz * mz);
  if (len > 0) { mx /= len; mz /= len; }
  const acc = 14;
  const moving = len > 0;
  vx += (mx * MOVE_SPEED - vx) * acc * dt;
  vz += (mz * MOVE_SPEED - vz) * acc * dt;
  if (!moving) { vx *= Math.pow(0.4, dt); vz *= Math.pow(0.4, dt); }

