  if (Math.abs(camera.position.y - gh) < 0.3) {
    camera.position.y = gh; vy = 0; onGround = true;
  } else {
    vy -= GRAVITY * dt;
    camera.position.y += vy * dt;
    const gh2 = groundHeightAt(camera.position.x, camera.position.z);
    if (camera.position.y < gh2) { camera.position.y = gh2; vy = 0; onGround = true; }
  }
  if ((keys['Space'] || window.__mjump) && onGround) { vy = JUMP; onGround = false; camera.position.y += 0.1; }
  window.__mjump = false;

  if (keys['KeyE'] && time - lastInteract > 350) { lastInteract = time; interact(); }

