      setKnob(stickOrigin.x, stickOrigin.y);
    } else {
      lookTouches[t.identifier] = { x: p.x, y: p.y, yaw, pitch };
    }
  }
}, { passive: false });

canvas.addEventListener('touchmove', (e) => {
  e.preventDefault();
  for (const t of e.changedTouches) {
    const p = tpos(t);
    if (t.identifier === stickId && stickActive) {
      const dx = p.x - stickOrigin.x, dy = p.y - stickOrigin.y;
      const d = Math.hypot(dx, dy);
      if (d > 10) {
        stick.x = dx / d; stick.y = -dy / d; // up on screen = forward
        const k = Math.min(d, STICK_R);
        setKnob(stickOrigin.x + (dx / d) * k, stickOrigin.y + (dy / d) * k);
      } else {
        stick.x = 0; stick.y = 0; setKnob(p.x, p.y);
      }
    } else if (lookTouches[t.identifier] !== undefined) {
      const lt = lookTouches[t.identifier];
      yaw += (p.x - lt.x) * LOOK_SENS;
