const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--touch-events=enabled', '--enable-features=TouchEvents'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  const errors = [];
  page.on('pageerror', e => { errors.push(e.message); if(errors.length<=5) console.log('PAGE:', e.message); });
  await page.goto('http://localhost:3107/index.html', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.waitForTimeout(700);

  const env = await page.evaluate(() => ({
    hasTouch: !!('ontouchstart' in window),
    maxTouch: navigator.maxTouchPoints,
    mobileEl: !!document.getElementById('joystick'),
    btnJump: !!document.getElementById('btnJump'),
    btnInteract: !!document.getElementById('btnInteract'),
    touchClass: document.body.classList.contains('touch-device'),
    prompt: document.getElementById('prompt').textContent,
  }));
  console.log('ENV:', JSON.stringify(env));

  // hide start screen + loader to enter game (simulate tap on start)
  await page.evaluate(() => {
    document.getElementById('start').style.display = 'none';
    document.getElementById('loader').style.display = 'none';
  });
  await page.waitForTimeout(600);

  // simulate joystick drag forward + look right
  await page.evaluate(() => {
    const c = document.getElementById('canvas');
    const r = c.getBoundingClientRect();
    // touchstart joystick at left area
    const tstart = new TouchEvent('touchstart', {
      cancelable: true, bubbles: true,
      touches: [new Touch({ identifier: 1, target: c, clientX: r.left + 40, clientY: r.top + r.height - 60, radiusX: 8, radiusY: 8, force: 1 })],
      changedTouches: [new Touch({ identifier: 1, target: c, clientX: r.left + 40, clientY: r.top + r.height - 60, radiusX: 8, radiusY: 8, force: 1 })]
    });
    c.dispatchEvent(tstart);
    // touchmove drag up (forward)
    const tmove = new TouchEvent('touchmove', {
      cancelable: true, bubbles: true,
      touches: [new Touch({ identifier: 1, target: c, clientX: r.left + 40, clientY: r.top + r.height - 120, radiusX: 8, radiusY: 8, force: 1 })],
      changedTouches: [new Touch({ identifier: 1, target: c, clientX: r.left + 40, clientY: r.top + r.height - 120, radiusX: 8, radiusY: 8, force: 1 })]
    });
    c.dispatchEvent(tmove);
  });
  await page.waitForTimeout(600);

  // tap interact button
  await page.evaluate(() => document.getElementById('btnInteract').dispatchEvent(new TouchEvent('touchstart',{cancelable:true,bubbles:true})));
  await page.evaluate(() => document.getElementById('btnInteract').dispatchEvent(new Event('mousedown',{cancelable:true,bubbles:true})));
  await page.waitForTimeout(300);

  const after = await page.evaluate(() => {
    return {
      stick: JSON.stringify(window.__dbg && window.__dbg.stick ? window.__dbg.stick() : 'n/a'),
      label: document.getElementById('label').textContent,
      promptShown: getComputedStyle(document.getElementById('prompt')).display !== 'none',
    };
  });
  console.log('AFTER:', JSON.stringify(after));

  await page.screenshot({ path: '/tmp/opencode/mobile-game.jpg', type: 'jpeg', quality: 78, timeout: 15000 });
  console.log('mobile screenshot ok');
  await browser.close();
  console.log('done. errors:', errors.length);
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

